"""Fixed W015 comparison. All permission and tool responses are synthetic."""
from pathlib import Path
import contextlib, copy, hashlib, importlib.util, inspect, io, json, sys, tempfile

TRIAL = Path(__file__).resolve().parents[1]
ACTIONS = ['export', 'transfer', 'create-notebooks', 'import-sources', 'read-sources', 'query-batches']

def module(name, path):
    spec = importlib.util.spec_from_file_location(name, path)
    value = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(value)
    return value

version = sys.argv[1]
bulk = module('bulk_'+version, TRIAL/version/'skills/research-workflow/scripts/bulk_literature.py')
fakes = module('fixed_fakes', TRIAL/'baseline/tests/test_bulk_literature.py')
fakes.bulk = bulk
sha = lambda data: hashlib.sha256(data).hexdigest()
results = []

class Case:
    def __init__(self, root):
        self.root = root
        self.log = root/'review.json'
        self.source = root/'decision.txt'
        self.source.write_text('SYNTHETIC FIXTURE. Researcher waives the listed intermediate reviews for this bounded fake run.\n')
        self.config = root/'config.json'
        self.config.write_text(json.dumps({'collection_key':'TESTCOL','question':'Which evidence supports the method?','remote':'drive:literature','run_dir':'run-2026-10-24','source_limit':2,'batch_size':1,'max_queries':2}))
        self.settings = bulk.load_config(self.config)
        self.tools = fakes.FakeTools()
        self.pipe = self.pipeline()
        self.event = {'event_id':'D001','supersedes':None,'researcher':'Synthetic researcher','source':{'path':'decision.txt','sha256':sha(self.source.read_bytes())},'kind':'waiver','status':'active','actions':ACTIONS,'expires_at':'2099-01-01T00:00:00+00:00'}
        self.record = {'schema_version':1,'run_id':self.pipe.run_id,'config_hash':self.pipe.config_hash,'events':[self.event]}
        self.save()
    def pipeline(self):
        if 'review_log' in inspect.signature(bulk.Pipeline).parameters:
            return bulk.Pipeline(self.settings,self.tools,review_log=self.log)
        p=bulk.Pipeline(self.settings,self.tools)
        p.review_log=self.log
        return p
    def save(self):
        self.log.write_text(json.dumps(self.record))
    def revoke(self):
        event=copy.deepcopy(self.event)
        event.update(event_id='D002',supersedes='D001',status='revoked')
        self.record['events'].append(event)
        self.save()
    def run(self, function=None):
        try:
            return {'result':(function or self.pipe.run)(),'error':None}
        except bulk.Stop as exc:
            return {'result':None,'error':str(exc)}
    def snapshot(self):
        return {str(p.relative_to(self.pipe.root)):sha(p.read_bytes()) for p in self.pipe.root.rglob('*') if p.is_file()}

def run_case(name, setup, evaluate, function=None):
    with tempfile.TemporaryDirectory(prefix='w015-fixed-') as directory:
        c=Case(Path(directory))
        extra=setup(c)
        outcome=c.run((lambda:function(c)) if function else None)
        passed, observation=evaluate(c,outcome,extra)
        results.append({'case':name,'meets_new_criteria':passed,'outcome':outcome,'calls':c.tools.calls,'run_files':c.snapshot(),'observation':observation,'supplied_log':c.log.read_text() if c.log.exists() else None})

def denied(c,outcome,extra):
    ok=bool(outcome['error']) and not c.tools.calls and not c.pipe.root.exists()
    return ok,'Expected denial with no external calls or run files.'

def mutate(fn):
    def setup(c):
        fn(c)
        c.save()
    return setup

run_case('G01 missing log',lambda c:c.log.unlink(),denied)
run_case('G02 valid complete waiver',lambda c:None,lambda c,o,x:(o['result']=={'status':'complete','report':str(c.pipe.root/'REPORT.md')} and len(c.tools.calls)>0,'Expected normal completion with fake tools.'))
run_case('G03 configuration changed',mutate(lambda c:c.record.update(config_hash='0'*64)),denied)
run_case('G03 run identity changed',mutate(lambda c:c.record.update(run_id='another-run')),denied)
run_case('G04 partial scope',mutate(lambda c:c.event.update(actions=ACTIONS[:-1])),denied)
run_case('G04 approval instead of waiver',mutate(lambda c:c.event.update(kind='approval')),denied)
for status in ['revoked','rejected','ended','pending']:
    def setup(c,status=status):
        c.revoke();c.record['events'][-1]['status']=status;c.save()
    run_case('G05 latest '+status,setup,denied)
run_case('G06 expired waiver',mutate(lambda c:c.event.update(expires_at='2000-01-01T00:00:00+00:00')),denied)
def duplicate(c):
    c.record['events'].append(copy.deepcopy(c.event))
run_case('G07 duplicate decision',mutate(duplicate),denied)
def broken(c):
    c.revoke();c.record['events'][-1]['supersedes']='Missing'
run_case('G07 broken history',mutate(broken),denied)
run_case('G07 duplicate JSON key',lambda c:c.log.write_text(c.log.read_text().replace('"schema_version": 1','"schema_version": 1, "schema_version": 1')),denied)
run_case('G07 nonfinite value',lambda c:c.log.write_text(c.log.read_text().replace('"schema_version": 1','"schema_version": NaN')),denied)
run_case('G08 missing source',lambda c:c.source.unlink(),denied)
run_case('G08 changed source',lambda c:c.source.write_text('Changed synthetic source.\n'),denied)
def revoke_midway(c):
    real=c.pipe.runner
    def runner(args,**kwargs):
        answer=real(args,**kwargs)
        if len(c.tools.calls)==1:c.revoke()
        return answer
    c.pipe.runner=runner
run_case('G09 revoke between commands',revoke_midway,lambda c,o,x:(bool(o['error']) and len(c.tools.calls)==1 and not c.pipe.root.exists(),'Expected only the already dispatched command.'))
def unknown(c):
    c.tools.fail='ask'
    first=c.run()
    assert first['error'],'Fixture must create a pending unknown query.'
    before=c.snapshot(); c.tools.calls.clear(); c.revoke();c.pipe=c.pipeline()
    return before
run_case('G10 unknown outcome and revoked waiver',unknown,lambda c,o,x:(bool(o['error']) and not c.tools.calls and c.snapshot()==x,'Expected no calls and byte-preserved existing run files.'))
def completed(c):
    assert c.run()['error'] is None
    c.tools.calls.clear();c.pipe=c.pipeline()
def no_replay(c,o,x):
    forbidden=[a for a in c.tools.calls if (a[0]=='zpm' and a[1]=='export') or (a[0]=='notebooklm' and (a[1] in ['create','ask'] or a[1:3]==['source','add-drive']))]
    return o['error'] is None and not forbidden,'Expected valid recovery without repeated completed work.'
run_case('G11 resume complete',completed,no_replay)
run_case('G12 plan no log',lambda c:c.log.unlink(),lambda c,o,x:(not c.tools.calls and not c.pipe.root.exists() and isinstance(o['result'],dict) and all(k in o['result'] for k in ['config_hash','run_id','required_actions']),'Expected zero effects and exact binding values.'),lambda c:c.pipe.plan())
run_case('G13 direct call without log',lambda c:c.log.unlink(),denied,lambda c:c.pipe.call(['notebooklm','--version']))
def cli(c):
    original=bulk.Pipeline
    class FakePipeline(original):
        def __init__(self,settings,**kwargs):
            super().__init__(settings,runner=c.tools,**kwargs)
    bulk.Pipeline=FakePipeline
    output=io.StringIO()
    try:
        with contextlib.redirect_stdout(output),contextlib.redirect_stderr(output):
            code=bulk.main([str(c.config),'--execute'])
    finally:bulk.Pipeline=original
    return {'exit_code':code,'output':output.getvalue()}
run_case('G13 CLI execute without log',lambda c:c.log.unlink(),lambda c,o,x:(o['result']['exit_code']==1 and not c.tools.calls and not c.pipe.root.exists(),'Expected CLI stop without invoking fake tools.'),cli)
record={'version':version,'runtime':sys.version,'code_sha256':sha((TRIAL/version/'skills/research-workflow/scripts/bulk_literature.py').read_bytes()),'fixed_criteria_sha256':sha((TRIAL/'evaluation/fixed-cases.json').read_bytes()),'count':len(results),'met':sum(r['meets_new_criteria'] for r in results),'results':results,'limits':['All decision text is synthetic. Baseline does not implement the new log API. The baseline adapter exposes the same supplied log as an unused attribute.','FakeTools code is loaded from the saved baseline and used for both versions. No live clients or accounts are invoked.','The matrix tests the new deterministic contract, not model reliability or authenticated consent.']}
(TRIAL/'evaluation'/('comparison-'+version+'.json')).write_text(json.dumps(record,indent=2)+'\n')
print(json.dumps({'version':version,'met':record['met'],'count':record['count'],'failed':[r['case'] for r in results if not r['meets_new_criteria']]}))

